    "summary": "Grant an agent delegation",
    "description": "Experimental/private beta. Grants an active sponsored agent a bounded set of event capabilities for one to 100 event scopes and at most 30 days. The server rechecks sponsor permissions and resource membership under lock, then derives the immutable permission snapshot and issue time.",
    "security": [
      {
        "BearerAuth": []
      }
    ],
    "requiredPermissions": [
      "developers.write"
    ],
